<?php
require_once '../includes/config.php';
if(!$pdo){http_response_code(500);echo '<h2>Database connection unavailable.</h2><p>Import database.sql and confirm XAMPP MySQL is running.</p>';exit;}
$members=$pdo->query('SELECT * FROM membership_inquiries ORDER BY created_at DESC LIMIT 50')->fetchAll();
$bookings=$pdo->query('SELECT * FROM tee_bookings ORDER BY tee_date,tee_time LIMIT 50')->fetchAll();
$messages=$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC LIMIT 50')->fetchAll();
$events=$pdo->query('SELECT * FROM events ORDER BY event_date,event_time')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K.O. Divinii Admin</title><link rel="stylesheet" href="../assets/css/style.css"><style>body{padding-top:100px}.admin-wrap{width:min(1200px,calc(100% - 30px));margin:auto}.admin-table{width:100%;border-collapse:collapse;font-size:11px}.admin-table th,.admin-table td{text-align:left;padding:11px;border-bottom:1px solid rgba(242,235,215,.08);vertical-align:top}.admin-table th{color:#9ea99b;text-transform:uppercase;letter-spacing:.12em;font-size:8px}.admin-section{margin:35px 0}.admin-title{font-size:42px;margin-bottom:15px}.pill{display:inline-block;border:1px solid rgba(212,179,106,.25);border-radius:999px;padding:5px 8px;font-size:8px;text-transform:uppercase;letter-spacing:.1em}.small-text{color:#849184;font-size:10px}</style></head><body><header class="topbar scrolled" style="position:fixed"><div class="brand"><span class="brand-mark"><img src="../assets/img/jc-logo.svg" alt="JC"></span><span class="brand-copy"><b>K.O. DIVINII</b><small>LOCAL ADMIN</small></span></div><a class="topbar-cta" href="../index.php">View site</a></header><main><div class="admin-wrap"><div class="section-kicker">Local administration</div><h1 class="admin-title">Club desk</h1><p class="small-text">Development-only dashboard for the XAMPP build. Add authentication before deployment.</p><section class="card admin-section"><div class="section-kicker">Membership enquiries (<?=count($members)?>)</div><table class="admin-table"><tr><th>Name</th><th>Email</th><th>Phone</th><th>Interest</th><th>Received</th></tr><?php foreach($members as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['email'])?></td><td><?=e($m['phone'])?></td><td><span class="pill"><?=e($m['membership_type'])?></span></td><td><?=e($m['created_at'])?></td></tr><?php endforeach;?></table></section><section class="card admin-section"><div class="section-kicker">Tee requests (<?=count($bookings)?>)</div><table class="admin-table"><tr><th>Player</th><th>Date</th><th>Time</th><th>Players</th><th>Status</th><th>Note</th></tr><?php foreach($bookings as $b):?><tr><td><?=e($b['name'])?><br><span class="small-text"><?=e($b['email'])?></span></td><td><?=e($b['tee_date'])?></td><td><?=e(date('g:i A',strtotime($b['tee_time'])))?></td><td><?=e($b['players'])?></td><td><span class="pill"><?=e($b['status'])?></span></td><td><?=e($b['notes'])?></td></tr><?php endforeach;?></table></section><section class="card admin-section"><div class="section-kicker">Messages (<?=count($messages)?>)</div><table class="admin-table"><tr><th>Name</th><th>Email</th><th>Subject</th><th>Message</th><th>Received</th></tr><?php foreach($messages as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['email'])?></td><td><?=e($m['subject'])?></td><td><?=nl2br(e($m['message']))?></td><td><?=e($m['created_at'])?></td></tr><?php endforeach;?></table></section><section class="card admin-section"><div class="section-kicker">Event calendar (<?=count($events)?>)</div><table class="admin-table"><tr><th>Event</th><th>Category</th><th>Date</th><th>Time</th><th>Location</th></tr><?php foreach($events as $e0):?><tr><td><?=e($e0['title'])?><br><span class="small-text"><?=e($e0['description'])?></span></td><td><?=e($e0['category'])?></td><td><?=e($e0['event_date'])?></td><td><?=e(date('g:i A',strtotime($e0['event_time'])))?></td><td><?=e($e0['location'])?></td></tr><?php endforeach;?></table></section></div></main></body></html>
